package main

const jsConversations = `
async function copyMessage(text){if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(text);}else{const area=el("textarea");area.value=text;area.readOnly=true;document.body.append(area);area.select();const copied=document.execCommand("copy");area.remove();if(!copied)throw Error("無法自動複製，請選取文字複製");}notice("已複製");}
function safeMessageLink(raw){if(/[\u0000-\u0020\u007f]/.test(raw))return null;try{const u=new URL(raw);return ["https:","http:"].includes(u.protocol)&&!u.username&&!u.password?u.href:null;}catch{return null;}}
function markdownInline(parent,text,depth=0){if(depth>3||text.length>16000){parent.append(document.createTextNode(text));return;}const pattern=/\x60([^\x60\n]+)\x60|\*\*([^*\n]+)\*\*|__([^_\n]+)__|\*([^*\n]+)\*|\[([^\]\n]+)\]\(([^\s)]+)\)/g;let last=0,count=0;for(const m of text.matchAll(pattern)){if(count++>256)break;parent.append(document.createTextNode(text.slice(last,m.index)));let node;if(m[1]!==undefined){node=el("code",m[1]);}else if(m[2]!==undefined||m[3]!==undefined){node=el("strong");markdownInline(node,m[2]??m[3],depth+1);}else if(m[4]!==undefined){node=el("em");markdownInline(node,m[4],depth+1);}else{const href=safeMessageLink(m[6]);if(href&&text[m.index-1]!=="!"){node=el("a",m[5]);node.href=href;node.target="_blank";node.rel="noopener noreferrer";}else node=document.createTextNode(m[0]);}parent.append(node);last=m.index+m[0].length;}parent.append(document.createTextNode(text.slice(last)));}
function markdownCells(line){return line.trim().replace(/^\|/,'').replace(/\|$/,'').split('|').map(s=>s.trim());}
function renderMarkdown(node,source){node.replaceChildren();node.dataset.raw=source;node.classList.add("rich-text");if(source.length>131072){node.textContent=source;node.classList.remove("rich-text");return;}const lines=source.replace(/\r\n?/g,"\n").split("\n");let i=0,blocks=0;while(i<lines.length){if(blocks++>1024){node.append(el("p",lines.slice(i).join("\n")));break;}const line=lines[i];if(!line.trim()){i++;continue;}const fence=line.match(/^\s{0,3}(\x60{3,}|~{3,})([^\s]*)\s*$/);if(fence){const code=[],start=fence[1],lang=fence[2].slice(0,40);i++;while(i<lines.length&&!new RegExp("^\\s{0,3}"+start[0]+"{"+start.length+",}\\s*$").test(lines[i]))code.push(lines[i++]);if(i<lines.length)i++;const box=el("div",undefined,"code-block"),bar=el("div",undefined,"code-toolbar"),pre=el("pre"),value=code.join("\n");bar.append(el("span",lang||"程式碼"));action(bar,"複製程式碼",()=>copyMessage(value));pre.append(el("code",value));box.append(bar,pre);node.append(box);continue;}
 if(i+1<lines.length&&line.includes('|')&&/^\s*\|?\s*:?-{3,}:?\s*(\|\s*:?-{3,}:?\s*)+\|?\s*$/.test(lines[i+1])){const wrap=el("div",undefined,"table-scroll"),table=el("table"),head=el("thead"),row=el("tr"),headers=markdownCells(line),body=el("tbody");headers.forEach(t=>{const th=el("th");th.scope="col";markdownInline(th,t);row.append(th);});head.append(row);table.append(head,body);i+=2;let n=0;while(i<lines.length&&lines[i].includes('|')&&lines[i].trim()&&n++<100){const tr=el("tr"),cells=markdownCells(lines[i++]);headers.forEach((_,j)=>{const td=el("td");markdownInline(td,cells[j]||"");tr.append(td);});body.append(tr);}wrap.tabIndex=0;wrap.setAttribute("role","region");wrap.setAttribute("aria-label","模型回應表格");wrap.append(table);node.append(wrap);continue;}
 const heading=line.match(/^\s{0,3}(#{1,6})\s+(.+)/);if(heading){const h=el("h"+Math.min(heading[1].length+1,6));markdownInline(h,heading[2]);node.append(h);i++;continue;}if(/^\s*([-*_])(?:\s*\1){2,}\s*$/.test(line)){node.append(el("hr"));i++;continue;}
 if(/^\s*>\s?/.test(line)){const quote=el("blockquote");while(i<lines.length&&/^\s*>/.test(lines[i])){markdownInline(quote,lines[i++].replace(/^\s*>\s?/,""));quote.append(el("br"));}node.append(quote);continue;}
 const list=line.match(/^\s{0,3}([-+*]|\d{1,6}[.)])\s+(.+)/);if(list){const ordered=/\d/.test(list[1]),ul=el(ordered?"ol":"ul");if(ordered)ul.start=parseInt(list[1],10);while(i<lines.length){const m=lines[i].match(/^\s{0,3}([-+*]|\d{1,6}[.)])\s+(.+)/);if(!m||/\d/.test(m[1])!==ordered)break;const li=el("li");markdownInline(li,m[2]);ul.append(li);i++;}node.append(ul);continue;}
 const p=el("p");markdownInline(p,line);node.append(p);i++;
 }}
function messageNode(role,text,{copy=true,rich=true}={}){const article=el("article",undefined,"message "+(role==="user"?"user":"assistant")),content=el("div",undefined,"bubble "+(role==="user"?"user":"assistant"));content.dataset.raw=text;if(role!=="user"&&rich)renderMarkdown(content,text);else content.textContent=text;article.append(content);if(copy&&text){const actions=el("div",undefined,"message-actions");action(actions,"複製訊息",()=>copyMessage(content.dataset.raw??content.textContent));article.append(actions);}return {article,content};}
function historyMessage(target,m,prepend=false){const fragment=document.createDocumentFragment();if(m.content){const {article}=messageNode(m.role,m.content);article.dataset.messageId=m.id;if(m.sample_id&&(m.role==="assistant"||m.request_outcome!=="SUCCESS")){const actions=article.querySelector(".message-actions")||el("div",undefined,"message-actions");if(!actions.parentElement)article.append(actions);requestLink(actions,m.sample_id);}fragment.append(article);}if(m.tool_calls?.length){const info=el("details",undefined,"message-extra");info.append(el("summary","工具呼叫："+m.tool_calls.map(c=>c.function?.name||c.name).join("、")),el("pre",JSON.stringify(m.tool_calls,null,2)));fragment.append(info);}if(m.attachments?.length)fragment.append(el("small","附件："+m.attachments.map(a=>a.filename).join("、"),"message-extra"));if(prepend)target.prepend(fragment);else target.append(fragment);}
async function sessionSelectRefresh(preferred=$("session").value||lastConversationByScope.get($("target").value)||""){const target=$("target").value;if(!target||!chatOperation(selectedOperation())){$("session").replaceChildren();sessions=[];renderRecentConversations();return;}const version=++sessionListVersion;const rows=await api("/sessions?"+query(JSON.parse(target))+"&limit=200");if(preferred&&!rows.some(s=>s.id===preferred)){const selected=await api("/sessions?"+query(JSON.parse(target))+"&session_id="+encodeURIComponent(preferred));rows.push(...selected);}if(version!==sessionListVersion||target!==$("target").value)return;applySessionRows(rows,target,preferred);conversationListReadComplete(target);refreshSidebarSessions().catch(()=>{});return true;}
function applySessionRows(rows,target,preferred){sessionScope=target;sessions=rows;$("session").replaceChildren();rows.forEach(s=>option($("session"),s.id,(s.pinned?"★ ":"")+s.title));if(rows.some(s=>s.id===preferred))$("session").value=preferred;$("conversation-title").textContent=rows.find(s=>s.id===$("session").value)?.title||"新對話";$("conversation-manage").disabled=busy||!$("session").value;renderRecentConversations();}
let sessionListVersion=0,libraryVersion=0,sessionScope="";
function bindConversations(){$("conversation-library").addEventListener("click",()=>conversationLibrary().catch(e=>notice(e.message,true)));$("conversation-manage").addEventListener("click",()=>{const s=sessions.find(s=>s.id===$("session").value);if(s)conversationDetail(s);});}
` + jsConversationWorkspace
